import java.nio.file.*;import java.util.*;import java.io.*;
/** Optional server-side economy/combat tuning, validated once at startup. */
final class TribalConfig {
 static void load()throws IOException {String configured=CloudStore.env("GUNNY_TRIBAL_CONFIG");Path file=Path.of(configured.isEmpty()?"tribal.properties":configured);if(!Files.isRegularFile(file)){if(!configured.isEmpty())throw new IOException("Missing tribal configuration");return;}Properties p=new Properties();try(var in=Files.newInputStream(file)){p.load(in);}array(p,"hp",TribalRules.HP,100,17000);array(p,"damage",TribalRules.DAMAGE,1,1000);array(p,"waves",TribalRules.WAVES,1,6);array(p,"stone_min",TribalRules.STONE_MIN,1,300);array(p,"stone_max",TribalRules.STONE_MAX,1,300);for(int i=0;i<3;i++)if(TribalRules.STONE_MIN[i]>TribalRules.STONE_MAX[i])throw new IOException("Invalid tribal reward range");TribalRules.reviveRounds=number(p,"revive_rounds",2,1,5);}
 static int number(Properties p,String key,int fallback,int min,int max)throws IOException{int value;try{value=Integer.parseInt(p.getProperty(key,""+fallback));}catch(NumberFormatException bad){throw new IOException("Invalid tribal configuration: "+key);}if(value<min||value>max)throw new IOException("Tribal configuration out of range: "+key);return value;}
 static void array(Properties p,String key,int[] target,int min,int max)throws IOException {String text=p.getProperty(key);if(text==null)return;String[] parts=text.split(",");if(parts.length!=target.length)throw new IOException("Invalid tribal array: "+key);for(int i=0;i<target.length;i++){Properties one=new Properties();one.setProperty(key,parts[i].trim());target[i]=number(one,key,target[i],min,max);}}
}
